//! Canonical Option interface over actual native and inert HTML records.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select><option id=option value=one>One</option></select><datalist id=choices><option id=suggestion value=two>Two</option></datalist><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://option-interface.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]fn option_interface_canonical_constructor_prototype_and_no_construction(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var C=HTMLOptionElement,P=C.prototype,x=document.getElementById('option'),g=Object.getOwnPropertyDescriptor(window,'HTMLOptionElement'),tag=Object.getOwnPropertyDescriptor(P,Symbol.toStringTag);if(!(x instanceof C)||!(x instanceof HTMLElement)||Object.getPrototypeOf(x)!==P||Object.getPrototypeOf(P)!==HTMLElement.prototype||Object.getPrototypeOf(C)!==HTMLElement||P.constructor!==C||C.name!=='HTMLOptionElement'||C.length!==0||g.value!==C||g.enumerable||!g.writable||!g.configurable||tag.value!=='HTMLOptionElement'||tag.writable||tag.enumerable||!tag.configurable)throw 'canonical Option';for(var mode of [0,1,2]){var caught=false;try{if(mode===0)C();else if(mode===1)new C();else new (C.bind(null))();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal Option constructor';}
"#);}
#[test]fn option_interface_exact_factories_namespaces_and_inherited_actual_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),P=HTMLOptionElement.prototype;if(!(document.getElementById('suggestion') instanceof HTMLOptionElement))throw 'actual datalist option';for(var x of [document.getElementById('option'),document.createElement('OPTION'),owner.createElementNS('http://www.w3.org/1999/xhtml','t:option')]){if(!(x instanceof HTMLOptionElement)||Object.getPrototypeOf(x)!==P||x.localName!=='option')throw 'actual Option factory';x.id='A\udfffZ';var attr=x.getAttributeNode('id');if(x.id!=='A\udfffZ'||attr.ownerElement!==x||attr.value!==x.id||Object.hasOwn(x,'id'))throw 'inherited exact Option attributes';}for(var wrong of [document.createElementNS('urn:foreign','option'),owner.createElementNS('http://www.w3.org/1999/xhtml','OPTION'),document.createElement('div'),document.createElement('x-option')])if(wrong instanceof HTMLOptionElement)throw 'exact Option interface boundary';
"#);}
#[test]fn option_interface_child_owner_and_saved_identity_after_global_deletion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var C=HTMLOptionElement,P=C.prototype,x=document.getElementById('option'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow.HTMLOptionElement;if(child===C||child.prototype.constructor!==child||Object.getPrototypeOf(child.prototype)!==frame.contentWindow.HTMLElement.prototype)throw 'child Option canonical owner';delete window.HTMLOptionElement;if(!(x instanceof C)||Object.getPrototypeOf(document.createElement('option'))!==P||P.constructor!==C)throw 'retained Option authority';
"#);}

#[test]fn option_interface_author_prototype_grants_no_native_element_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'id'),calls=0;for(var bad of [{},Object.create(HTMLOptionElement.prototype)]){var caught=false;try{descriptor.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'Option author prototype is not a native Element';}var C=HTMLOptionElement,P=C.prototype;P.constructor=17;delete window.HTMLOptionElement;if(Object.getPrototypeOf(document.createElement('option'))!==P||P.constructor!==17)throw 'Option prototype mutation cannot replace native identity';");}
#[test]fn option_interface_saved_child_inherited_access_checks_origin_before_hooks(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.Element.prototype,'id'),calls=0;");p.set_location(&crate::navigation::address("https://other-option-interface.test/",&crate::navigation::Location::home()).unwrap());let tree=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute("descriptor.set.call(x,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://option-interface.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'Option origin before hooks';descriptor.set.call(x,'recovered');if(x.id!=='recovered'||!(x instanceof HTMLOptionElement))throw 'Option fresh origin recovery';");}
